fix.code:
// Cách 1: cập nhật nguyên tử, điều kiện số dư nằm trong chính câu UPDATE
public interface WalletRepository extends JpaRepository<Wallet, Long> {
    @Modifying
    @Query("update Wallet w set w.balance = w.balance - :amount "
         + "where w.id = :id and w.balance >= :amount")
    int withdraw(@Param("id") long id, @Param("amount") long amount);
}

@Transactional
public void withdraw(long walletId, long amount) {
    if (walletRepository.withdraw(walletId, amount) == 0) {
        throw new InsufficientBalanceException(walletId);
    }
}

// Cách 2: khoá bi quan khi cần đọc entity rồi xử lý nhiều bước
@Lock(LockModeType.PESSIMISTIC_WRITE)            // sinh SELECT ... FOR UPDATE
@Query("select w from Wallet w where w.id = :id")
Optional<Wallet> findForUpdate(@Param("id") long id);

